<h1>Dashboard</h1><p class="muted">Ringkasan administrasi Ma'had · <?=date('d/m/Y')?></p><div class="grid"><?php if(can_view('peserta')): ?><section class="card"><h3>Jumlah Peserta</h3><div class="number"><?=(int)sql('SELECT COUNT(*) FROM participants')->fetchColumn()?></div><p>Aktif: <?=(int)sql("SELECT COUNT(*) FROM participants WHERE status='aktif'")->fetchColumn()?></p><a href="?page=peserta">Kelola peserta</a></section><?php endif; ?><?php if(can_view('aset')): ?><section class="card"><h3>Jumlah Aset</h3><div class="number"><?=(int)sql('SELECT COUNT(*) FROM assets')->fetchColumn()?></div><p>Nilai: <?=rupiah(sql('SELECT COALESCE(SUM(nilai_perolehan),0) FROM assets')->fetchColumn())?></p><a href="?page=aset">Lihat inventaris</a></section><?php endif; ?><?php if(can_view('keuangan')): $t=sql("SELECT COALESCE(SUM(CASE WHEN jenis='masuk' THEN nominal ELSE 0 END),0) masuk, COALESCE(SUM(CASE WHEN jenis='keluar' THEN nominal ELSE 0 END),0) keluar FROM transactions")->fetch(); foreach(['Total Pemasukan'=>$t['masuk'],'Total Pengeluaran'=>$t['keluar'],'Saldo Tercatat'=>(float)$t['masuk']-(float)$t['keluar']] as $label=>$value): ?><section class="card"><h3><?=esc($label)?></h3><div class="number"><?=rupiah($value)?></div></section><?php endforeach;endif; ?></div><?php if(can_view('laporan')): ?><p class="muted">Saldo merupakan selisih transaksi tercatat, belum merupakan rekonsiliasi kas dan bank.</p><a href="?page=laporan">Buka laporan keuangan</a><?php endif; ?>